import{_ as t,o as a,c as o,a3 as d}from"./chunks/framework.BNNhFWPR.js";const g=JSON.parse('{"title":"Project settings","description":"Every project setting, its default value and what it changes.","frontmatter":{"id":"project-settings","title":"Project settings","order":9,"description":"Every project setting, its default value and what it changes.","editUrl":"https://github.com/ATMO-Engine/atmo/edit/main/docs/en/manual/project-settings.md"},"headers":[],"relativePath":"manual/project-settings.md","filePath":"en/manual/project-settings.md"}'),r={name:"manual/project-settings.md"};function s(n,e,i,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="project-settings" tabindex="-1">Project settings <a class="header-anchor" href="#project-settings" aria-label="Permalink to &quot;Project settings&quot;">​</a></h1><p>Settings are stored in <code>.atmo/project_settings.json</code>, in the <a href="/latest/getting-started/projects#layout" class="atmo-ref atmo-ref--page" data-preview="Where projects are stored on your computer and how to reach their files with project:// paths.">project folder</a>. Change them in the editor with <strong>Project &gt; Project settings</strong> (Ctrl+Shift+P, Cmd+Shift+P on macOS), then <strong>Apply</strong>. Closing the window without <strong>Apply</strong> discards the changes.</p><p>Settings can also be edited in the file while the editor is closed, or with the <code>project_settings_set</code> tool of the <a href="/latest/manual/mcp-server" class="atmo-ref atmo-ref--page" data-preview="Let an AI agent drive the editor or a running game through the Model Context Protocol.">MCP server</a>. Missing settings keep their default value. In C++, they are in <a href="/latest/api/cpp/class/atmo-project-projectsettings" class="atmo-ref atmo-ref--symbol"><code>ProjectSettings</code></a>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Some settings are read when the engine starts, before the project is opened. They are ignored by the editor and by run mode, which includes the Play button. They are marked <a href="#late">late</a> below.</p></div><h2 id="app" tabindex="-1">App <a class="header-anchor" href="#app" aria-label="Permalink to &quot;App {#app}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>project_name</code></td><td><code>New Atmo Project</code></td><td>Title of the window, and <a href="/latest/getting-started/projects#user-paths" class="atmo-ref atmo-ref--page" data-preview="Where projects are stored on your computer and how to reach their files with project:// paths.">user:// folder</a> of exported games</td></tr><tr><td><code>default_scene</code></td><td>Empty</td><td><a href="/latest/getting-started/projects#default-scene" class="atmo-ref atmo-ref--page" data-preview="Where projects are stored on your computer and how to reach their files with project:// paths.">First scene</a> of the game</td></tr><tr><td><code>icon_path</code></td><td><code>project://assets/atmo.png</code></td><td>Not used yet</td></tr><tr><td><code>engine_version</code></td><td>Version of the engine</td><td>Only in the file. Set when the project is created.</td></tr><tr><td><code>project_version</code></td><td></td><td>Only in the file. Used in the name of <code>.pck</code> files.</td></tr></tbody></table><h2 id="boot" tabindex="-1">Boot <a class="header-anchor" href="#boot" aria-label="Permalink to &quot;Boot {#boot}&quot;">​</a></h2><p><code>background_color</code>, <code>show_splash_icon</code>, <code>full_size_splash_icon</code> and <code>splash_icon_path</code> are not used yet.</p><h2 id="window" tabindex="-1">Window <a class="header-anchor" href="#window" aria-label="Permalink to &quot;Window {#window}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>size</code></td><td>1280 by 720</td><td>Initial size of the window (<a href="#late">late</a>), and size that <code>stretch_mode</code> scales</td></tr><tr><td><code>background_color</code></td><td><code>#191919</code></td><td>Color behind the scene (<a href="#late">late</a> for the game window)</td></tr><tr><td><code>stretch_mode</code></td><td><code>disabled</code></td><td><code>disabled</code>, <code>fit</code> or <code>integer</code>: see <a href="/latest/manual/screen-sizes#stretch-mode" class="atmo-ref atmo-ref--page" data-preview="How scenes are scaled to the window and to HiDPI screens, and the project settings that control it.">Stretch mode</a></td></tr><tr><td><code>letterbox_color</code></td><td>Black</td><td>Color of the bars of <code>fit</code> and <code>integer</code> (<a href="#late">late</a>)</td></tr><tr><td><code>headless</code></td><td>No</td><td>Not used. Start the engine with <code>--headless</code> instead.</td></tr></tbody></table><p>The scene editor outlines <code>size</code> in the viewport.</p><h2 id="rendering" tabindex="-1">Rendering <a class="header-anchor" href="#rendering" aria-label="Permalink to &quot;Rendering {#rendering}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>texture_filter</code></td><td><code>linear</code></td><td><code>linear</code> or <code>nearest</code>: see <a href="/latest/manual/screen-sizes#texture-filter" class="atmo-ref atmo-ref--page" data-preview="How scenes are scaled to the window and to HiDPI screens, and the project settings that control it.">Texture filtering</a></td></tr></tbody></table><p>The settings window does not show this section: edit the file or use the <a href="/latest/manual/mcp-server" class="atmo-ref atmo-ref--page" data-preview="Let an AI agent drive the editor or a running game through the Model Context Protocol.">MCP server</a>.</p><h2 id="engine" tabindex="-1">Engine <a class="header-anchor" href="#engine" aria-label="Permalink to &quot;Engine {#engine}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>gravity</code></td><td>(0, 9.81, 0)</td><td>Gravity in m/s². <code>z</code> is not used.</td></tr><tr><td><code>physics_frame_rate</code></td><td>60</td><td>Physics steps per second (<a href="#late">late</a>)</td></tr><tr><td><code>pixels_per_meter</code></td><td>50</td><td>Conversion between pixels and meters: see <a href="/latest/manual/physics#units" class="atmo-ref atmo-ref--page" data-preview="Physics bodies and shapes, gravity and units, and how to move bodies.">Units</a></td></tr></tbody></table><h2 id="debug" tabindex="-1">Debug <a class="header-anchor" href="#debug" aria-label="Permalink to &quot;Debug {#debug}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>draw_physics_debug</code></td><td>Yes</td><td>Draws the collision shapes in the scene editor</td></tr><tr><td><code>draw_physics_debug_in_game</code></td><td>No</td><td>Draws them in the game (<a href="#late">late</a>)</td></tr></tbody></table><h2 id="singletons" tabindex="-1">Singletons <a class="header-anchor" href="#singletons" aria-label="Permalink to &quot;Singletons {#singletons}&quot;">​</a></h2><p><code>scenes</code> is not used yet.</p><h2 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP {#mcp}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>No</td><td>Starts the <a href="/latest/manual/mcp-server" class="atmo-ref atmo-ref--page" data-preview="Let an AI agent drive the editor or a running game through the Model Context Protocol.">MCP server</a> when the editor opens</td></tr><tr><td><code>port</code></td><td>27760</td><td>Port of the server</td></tr></tbody></table><h2 id="addons" tabindex="-1">Addons <a class="header-anchor" href="#addons" aria-label="Permalink to &quot;Addons {#addons}&quot;">​</a></h2><p>One checkbox per addon of the project: see <a href="/latest/manual/addons" class="atmo-ref atmo-ref--page" data-preview="Create addons that share assets or extend the engine with a native C++ library.">Addons</a>. The change applies the next time the project is opened.</p><h2 id="late" tabindex="-1">Late settings <a class="header-anchor" href="#late" aria-label="Permalink to &quot;Late settings {#late}&quot;">​</a></h2><p>When a project is opened with <code>--project</code>, the window and the game world are created before its settings are read, with the default values of the settings. This affects the settings marked above. Exported games read their settings first.</p>',26)])])}const f=t(r,[["render",s]]);export{g as __pageData,f as default};
